#!/usr/bin/env node
/* global process, TextDecoder */ // The root ESLint config declares no environment globals.
// Read the text of an ASCII DXF drawing with Node alone.
//
//   node dxf.mjs <file> [out.json]   → { version, codepage, layers, blocks, counts, texts, inserts, lines, circles }
//
// With `out.json` the same JSON is written to that file (its folder is created) and only
// `{ "written": "<out.json>" }` is printed, so a large drawing need not pass through the model.
//
// `texts` holds the words on the drawing: TEXT, MTEXT (formatting codes removed), ATTRIB and
// ATTDEF values, and the text and measurement of DIMENSION entities. Geometry is summarised as
// `counts` of each entity type, plus the coordinates of the two primitives a part drawing is made
// of: `lines` (LINE) and `circles` (CIRCLE). Every other shape is only counted. A binary DXF, a
// code page this reader does not know, and a file that is not a DXF are refused by name.
import { mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { pathToFileURL } from 'node:url';

/** A drawing is read whole and split into lines, so a file past this is refused by name. */
export const DXF_MAX_FILE_BYTES = 32 * 1024 * 1024;

function refuseLargeFile(size) {
  if (size > DXF_MAX_FILE_BYTES)
    throw new DxfRefusal(
      'file_too_large',
      `the file is ${size} bytes; at most ${DXF_MAX_FILE_BYTES} are read`,
    );
}

/** Why a file was refused; `code` is the name an agent reports. */
export class DxfRefusal extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'DxfRefusal';
    this.code = code;
  }
}

function pairsOf(text) {
  const lines = text.split(/\r?\n/u);
  const pairs = [];
  for (let at = 0; at + 1 < lines.length; at += 2) {
    const code = Number((lines[at] ?? '').trim());
    if (!Number.isInteger(code)) throw new DxfRefusal('not_a_dxf', 'the file is not an ASCII DXF');
    pairs.push([code, lines[at + 1] ?? '']);
  }
  return pairs;
}

function headerVariable(pairs, name) {
  const at = pairs.findIndex(([code, value]) => code === 9 && value.trim() === name);
  return at < 0 ? undefined : pairs[at + 1]?.[1]?.trim();
}

/** The TextDecoder label for a `$DWGCODEPAGE` name, or null when this reader has no table for it. */
function codepageLabel(codepage) {
  if (codepage === undefined || /^(?:ASCII|UNDEFINED)$/iu.test(codepage)) return 'windows-1252';
  const ansi = /^ANSI_(\d+)$/iu.exec(codepage);
  if (!ansi) return null;
  const number = Number(ansi[1]);
  const named = { 932: 'shift_jis', 936: 'gbk', 949: 'euc-kr', 950: 'big5', 874: 'windows-874' };
  if (named[number] !== undefined) return named[number];
  return number >= 1250 && number <= 1258 ? `windows-${number}` : null;
}

function decode(buffer) {
  refuseLargeFile(buffer.length);
  if (buffer.subarray(0, 18).toString('latin1') === 'AutoCAD Binary DXF')
    throw new DxfRefusal('binary_dxf', 'a binary DXF; export an ASCII DXF instead');
  // Header names are ASCII, so the version and code page can be read before the text is decoded.
  const header = pairsOf(buffer.toString('latin1'));
  const version = headerVariable(header, '$ACADVER');
  const codepage = headerVariable(header, '$DWGCODEPAGE');
  // From AutoCAD 2007 (AC1021) a DXF is UTF-8 whatever the code page says.
  const unicode = version !== undefined && version >= 'AC1021';
  const label = unicode ? 'utf-8' : codepageLabel(codepage);
  if (label === null)
    throw new DxfRefusal(
      'unsupported_codepage',
      `the code page ${codepage ?? ''} is not supported`,
    );
  try {
    return { text: new TextDecoder(label).decode(buffer), version, codepage };
  } catch {
    throw new DxfRefusal(
      'unsupported_codepage',
      `the code page ${codepage ?? ''} is not supported`,
    );
  }
}

const SPECIAL = { c: '⌀', d: '°', p: '±' };

/** TEXT and ATTRIB values: `\U+XXXX` escapes and `%%c`-style symbols. */
function plain(value) {
  return value
    .replace(/\\U\+([0-9A-Fa-f]{4})/gu, (_, hex) => String.fromCharCode(parseInt(hex, 16)))
    .replace(/%%([cdpCDP])/gu, (_, symbol) => SPECIAL[symbol.toLowerCase()] ?? '')
    .replace(/%%[uoUO]/gu, '');
}

/** MTEXT: fonts, colours, heights and the like are dropped; `\P` is a line break. */
function mtext(value) {
  return plain(value)
    .replace(
      /\\([\\{}])|\\P|\\~|\\S([^;]*);|\\[fFcCHhWwQqTtAa][^;]*;|\\[LlOoKk]|[{}]/gu,
      (match, escaped, stacked) => {
        if (escaped !== undefined) return escaped;
        if (match === '\\P') return '\n';
        if (match === '\\~') return ' ';
        return stacked ?? '';
      },
    )
    .trim();
}

const first = (pairs, code) => pairs.find(([c]) => c === code)?.[1];
const number = (pairs, code) => {
  const value = first(pairs, code);
  return value === undefined ? undefined : Number(value);
};

/** The fields that are there: a coordinate the entity left out stays out of the JSON. */
const present = (fields) =>
  Object.fromEntries(Object.entries(fields).filter(([, value]) => value !== undefined));

function entityText(type, pairs) {
  if (type === 'MTEXT')
    return mtext(
      pairs
        .filter(([code]) => code === 3)
        .map(([, value]) => value)
        .join('') + (first(pairs, 1) ?? ''),
    );
  if (type === 'TEXT' || type === 'ATTRIB' || type === 'ATTDEF' || type === 'DIMENSION')
    return plain(first(pairs, 1) ?? '').trim();
  return undefined;
}

/**
 * The text and structure of an ASCII DXF.
 *
 * @param {Buffer} buffer
 * @throws {DxfRefusal} `binary_dxf`, `unsupported_codepage`, `not_a_dxf` or `file_too_large`.
 */
export function readDxf(buffer) {
  const { text, version, codepage } = decode(buffer);
  const pairs = pairsOf(text);
  const start = pairs.findIndex(([code]) => code !== 999);
  if (pairs[start]?.[0] !== 0 || pairs[start]?.[1].trim() !== 'SECTION')
    throw new DxfRefusal('not_a_dxf', 'the file is not an ASCII DXF');

  const records = [];
  for (const pair of pairs.slice(start)) {
    if (pair[0] === 0) records.push({ type: pair[1].trim(), pairs: [] });
    else records.at(-1)?.pairs.push(pair);
  }

  const layers = [];
  const blocks = [];
  const counts = {};
  const texts = [];
  const inserts = [];
  const lines = [];
  const circles = [];
  let section = null;
  let block;
  for (const { type, pairs: body } of records) {
    if (type === 'SECTION') {
      section = first(body, 2)?.trim() ?? null;
      continue;
    }
    if (type === 'ENDSEC') section = null;
    else if (section === 'TABLES' && type === 'LAYER') layers.push(first(body, 2) ?? '');
    else if (section === 'BLOCKS' && type === 'BLOCK') {
      block = first(body, 2) ?? '';
      blocks.push(block);
    } else if (section === 'BLOCKS' && type === 'ENDBLK') block = undefined;
    else if (section === 'ENTITIES' || section === 'BLOCKS') {
      counts[type] = (counts[type] ?? 0) + 1;
      const layer = first(body, 8);
      const where = { ...(block === undefined ? {} : { block }), ...(layer ? { layer } : {}) };
      const [x, y] = [number(body, 10), number(body, 20)];
      const at = { ...(x === undefined ? {} : { x }), ...(y === undefined ? {} : { y }) };
      const size = number(body, 40);
      const value = entityText(type, body);
      if (type === 'INSERT') inserts.push({ name: first(body, 2) ?? '', ...where, ...at });
      if (type === 'LINE')
        lines.push({
          ...where,
          ...present({ x1: x, y1: y, x2: number(body, 11), y2: number(body, 21) }),
        });
      if (type === 'CIRCLE') circles.push({ ...where, ...at, ...present({ r: size }) });
      if (value !== undefined) {
        const measurement = type === 'DIMENSION' ? number(body, 42) : undefined;
        if (value !== '' || measurement !== undefined)
          texts.push({
            type,
            ...where,
            ...(type === 'ATTRIB' || type === 'ATTDEF' ? { tag: first(body, 2) ?? '' } : {}),
            text: value,
            ...(measurement === undefined ? {} : { measurement }),
            ...(type === 'DIMENSION' ? {} : present({ height: size })),
            ...at,
          });
      }
    }
  }
  return {
    version: version ?? null,
    codepage: codepage ?? null,
    layers,
    blocks,
    counts,
    texts,
    inserts,
    lines,
    circles,
  };
}

// ---------- command line ----------

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const [file, output] = process.argv.slice(2);
  if (file === undefined || process.argv.length > 4) {
    process.stderr.write('usage: node dxf.mjs <file> [out.json]\n');
    process.exit(2);
  }
  try {
    refuseLargeFile(statSync(file).size);
    const json = `${JSON.stringify(readDxf(readFileSync(file)), null, 2)}\n`;
    if (output === undefined) {
      process.stdout.write(json);
    } else {
      mkdirSync(dirname(output), { recursive: true });
      writeFileSync(output, json);
      process.stdout.write(`${JSON.stringify({ written: output })}\n`);
    }
  } catch (error) {
    if (!(error instanceof DxfRefusal)) throw error;
    process.stderr.write(`${JSON.stringify({ error: error.code, message: error.message })}\n`);
    process.exit(1);
  }
}

#!/usr/bin/env node
/* global Buffer, process */ // The root ESLint config declares no environment globals.
// Read (and, for test fixtures, write) .xlsx and .docx files with Node alone.
//
// An Office file is a zip of XML parts. This reads the zip's central directory, inflates the parts
// it needs with node:zlib, and pulls cells and paragraphs out of the XML with patterns narrow
// enough for the parts Excel and Word write. It is the script the office-reader skill runs inside
// a run's sandbox: the runtime image has Node, and a skill cannot bring npm packages with it.
//
//   node ooxml.mjs xlsx <file>   → { sheets: [{ name, rows, merges, cells }] }
//   node ooxml.mjs docx <file> [out.json]   → { paragraphs: [{ style, text }] }, printed or, with
//     `out.json`, written there (its folder is created) and answered with `{ "written": "<out.json>" }`
//   node ooxml.mjs write <spec.json> <out.xlsx|out.docx>   → the file, from { sheets } or { paragraphs }
import { mkdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { pathToFileURL } from 'node:url';
import { deflateRawSync, inflateRawSync } from 'node:zlib';

// ---------- zip ----------

const CRC_TABLE = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k += 1) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});

function crc32(buffer) {
  let crc = 0xffffffff;
  for (const byte of buffer) crc = CRC_TABLE[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}

/**
 * What one file may cost. An Office file comes from outside, and a few kilobytes of zip can inflate
 * to gigabytes, so the archive, the entry count and what every entry inflates to are all capped.
 */
export const OOXML_LIMITS = Object.freeze({
  fileBytes: 50 * 1024 * 1024,
  entries: 2_000,
  entryBytes: 64 * 1024 * 1024,
  totalBytes: 128 * 1024 * 1024,
});

/** Why a file was refused; `code` is the name an agent reports. */
export class OoxmlRefusal extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'OoxmlRefusal';
    this.code = code;
  }
}

function refuseLargeFile(size) {
  if (size > OOXML_LIMITS.fileBytes)
    throw new OoxmlRefusal(
      'archive_too_large',
      `the file is ${size} bytes; at most ${OOXML_LIMITS.fileBytes} are read`,
    );
}

function inflateEntry(name, data, remaining) {
  const limit = Math.max(1, Math.min(OOXML_LIMITS.entryBytes, remaining));
  try {
    return inflateRawSync(data, { maxOutputLength: limit });
  } catch (error) {
    if (error?.code !== 'ERR_BUFFER_TOO_LARGE') throw error;
    throw limit < OOXML_LIMITS.entryBytes
      ? new OoxmlRefusal(
          'archive_too_large',
          `the archive inflates to more than ${OOXML_LIMITS.totalBytes} bytes`,
        )
      : new OoxmlRefusal(
          'entry_too_large',
          `${name} inflates to more than ${OOXML_LIMITS.entryBytes} bytes`,
        );
  }
}

/**
 * The entries of a zip archive, by name, inflated. Supports stored and deflated entries.
 *
 * @throws {OoxmlRefusal} `archive_too_large`, `too_many_entries`, `entry_too_large` or
 *   `corrupt_archive`.
 */
export function readZip(buffer) {
  refuseLargeFile(buffer.length);
  try {
    return readEntries(buffer);
  } catch (error) {
    if (error instanceof OoxmlRefusal) throw error;
    throw new OoxmlRefusal('corrupt_archive', 'not a zip file (the archive could not be read)');
  }
}

function readEntries(buffer) {
  let end = buffer.length - 22;
  while (end >= 0 && buffer.readUInt32LE(end) !== 0x06054b50) end -= 1;
  if (end < 0) throw new Error('not a zip file (no end of central directory)');
  const count = buffer.readUInt16LE(end + 10);
  if (count > OOXML_LIMITS.entries)
    throw new OoxmlRefusal(
      'too_many_entries',
      `the archive lists ${count} entries; at most ${OOXML_LIMITS.entries} are read`,
    );
  let total = 0;
  let offset = buffer.readUInt32LE(end + 16);
  const entries = new Map();
  for (let index = 0; index < count; index += 1) {
    if (buffer.readUInt32LE(offset) !== 0x02014b50) throw new Error('corrupt central directory');
    const method = buffer.readUInt16LE(offset + 10);
    const compressedSize = buffer.readUInt32LE(offset + 20);
    const nameLength = buffer.readUInt16LE(offset + 28);
    const extraLength = buffer.readUInt16LE(offset + 30);
    const commentLength = buffer.readUInt16LE(offset + 32);
    const localOffset = buffer.readUInt32LE(offset + 42);
    const name = buffer.toString('utf8', offset + 46, offset + 46 + nameLength);
    const localNameLength = buffer.readUInt16LE(localOffset + 26);
    const localExtraLength = buffer.readUInt16LE(localOffset + 28);
    const start = localOffset + 30 + localNameLength + localExtraLength;
    const data = buffer.subarray(start, start + compressedSize);
    if (method !== 0 && method !== 8) throw new Error(`${name}: unsupported compression ${method}`);
    const content =
      method === 0 ? Buffer.from(data) : inflateEntry(name, data, OOXML_LIMITS.totalBytes - total);
    total += content.length;
    if (total > OOXML_LIMITS.totalBytes)
      throw new OoxmlRefusal(
        'archive_too_large',
        `the archive holds more than ${OOXML_LIMITS.totalBytes} bytes`,
      );
    entries.set(name, content);
    offset += 46 + nameLength + extraLength + commentLength;
  }
  return entries;
}

/** A deflated zip archive of `entries` ({ name, data: string | Buffer }), in order. */
export function writeZip(entries) {
  const locals = [];
  const centrals = [];
  let offset = 0;
  for (const entry of entries) {
    const name = Buffer.from(entry.name, 'utf8');
    const data = Buffer.isBuffer(entry.data) ? entry.data : Buffer.from(entry.data, 'utf8');
    const compressed = deflateRawSync(data);
    const crc = crc32(data);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0x0800, 6); // UTF-8 names
    local.writeUInt16LE(8, 8);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(compressed.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(name.length, 26);
    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(20, 4);
    central.writeUInt16LE(20, 6);
    central.writeUInt16LE(0x0800, 8);
    central.writeUInt16LE(8, 10);
    central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(compressed.length, 20);
    central.writeUInt32LE(data.length, 24);
    central.writeUInt16LE(name.length, 28);
    central.writeUInt32LE(offset, 42);
    locals.push(local, name, compressed);
    centrals.push(central, name);
    offset += local.length + name.length + compressed.length;
  }
  const directory = Buffer.concat(centrals);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0);
  end.writeUInt16LE(entries.length, 8);
  end.writeUInt16LE(entries.length, 10);
  end.writeUInt32LE(directory.length, 12);
  end.writeUInt32LE(offset, 16);
  return Buffer.concat([...locals, directory, end]);
}

// ---------- xml ----------

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };

function decode(value) {
  return value.replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/giu, (_, entity) => {
    if (entity[0] !== '#') return ENTITIES[entity];
    const code = entity[1] === 'x' ? Number.parseInt(entity.slice(2), 16) : Number(entity.slice(1));
    return String.fromCodePoint(code);
  });
}

function encode(value) {
  return String(value).replace(
    /[&<>"]/gu,
    (char) => `&${{ '&': 'amp', '<': 'lt', '>': 'gt', '"': 'quot' }[char]};`,
  );
}

function attribute(tag, name) {
  const match = new RegExp(`\\s${name}="([^"]*)"`, 'u').exec(tag);
  return match ? decode(match[1]) : null;
}

/** The concatenated text of every <t> (or <w:t>) element inside `xml`. */
function textOf(xml, tag = 't') {
  return [...xml.matchAll(new RegExp(`<${tag}(?:\\s[^>]*)?>([^<]*)</${tag}>`, 'gu'))]
    .map((match) => decode(match[1]))
    .join('');
}

// ---------- xlsx ----------

/** 'AA' → 26 (0-based). */
export function columnIndex(letters) {
  let index = 0;
  for (const char of letters) index = index * 26 + (char.charCodeAt(0) - 64);
  return index - 1;
}

/** 26 → 'AA'. */
export function columnLetters(index) {
  let letters = '';
  for (let n = index + 1; n > 0; n = Math.floor((n - 1) / 26)) {
    letters = String.fromCharCode(65 + ((n - 1) % 26)) + letters;
  }
  return letters;
}

function splitRef(ref) {
  const match = /^([A-Z]+)(\d+)$/u.exec(ref);
  if (!match) throw new Error(`not a cell reference: ${ref}`);
  return { column: columnIndex(match[1]), row: Number(match[2]) - 1 };
}

/**
 * Every sheet of an .xlsx file: `cells` keyed by reference as written, `merges` as ranges, and
 * `rows`, a dense 2-D array in which each merged range repeats its top-left value — what a person
 * sees on screen, and what folding a multi-row header needs.
 */
export function readXlsx(buffer) {
  const zip = readZip(buffer);
  const part = (name) => zip.get(name)?.toString('utf8') ?? '';
  const shared = [...part('xl/sharedStrings.xml').matchAll(/<si>([\s\S]*?)<\/si>/gu)].map((match) =>
    textOf(match[1]),
  );
  const targets = new Map(
    [...part('xl/_rels/workbook.xml.rels').matchAll(/<Relationship\b[^>]*>/gu)].map((match) => [
      attribute(match[0], 'Id'),
      attribute(match[0], 'Target'),
    ]),
  );
  const sheets = [...part('xl/workbook.xml').matchAll(/<sheet\b[^>]*>/gu)].map((match) => {
    const target = targets.get(attribute(match[0], 'r:id')) ?? '';
    const xml = part(target.startsWith('/') ? target.slice(1) : `xl/${target}`);
    const cells = {};
    let width = 0;
    let height = 0;
    for (const cell of xml.matchAll(/<c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/gu)) {
      const ref = attribute(` ${cell[1]}`, 'r');
      if (ref === null) continue;
      const type = attribute(` ${cell[1]}`, 't');
      const inner = cell[2] ?? '';
      const raw = /<v>([^<]*)<\/v>/u.exec(inner)?.[1];
      let value = null;
      if (type === 's') value = shared[Number(raw)] ?? null;
      else if (type === 'inlineStr') value = textOf(inner);
      else if (type === 'str') value = raw === undefined ? null : decode(raw);
      else if (type === 'b') value = raw === '1';
      else if (raw !== undefined) value = Number(raw);
      if (value === null || value === '') continue;
      cells[ref] = value;
      const { column, row } = splitRef(ref);
      width = Math.max(width, column + 1);
      height = Math.max(height, row + 1);
    }
    const merges = [...xml.matchAll(/<mergeCell\b[^>]*>/gu)].map((merge) =>
      attribute(merge[0], 'ref'),
    );
    const rows = Array.from({ length: height }, () => Array.from({ length: width }, () => null));
    for (const [ref, value] of Object.entries(cells)) {
      const { column, row } = splitRef(ref);
      rows[row][column] = value;
    }
    for (const range of merges) {
      const [from, to] = range.split(':').map(splitRef);
      const value = rows[from.row]?.[from.column] ?? null;
      for (let row = from.row; row <= to.row && row < height; row += 1) {
        for (let column = from.column; column <= to.column && column < width; column += 1)
          rows[row][column] = value;
      }
    }
    return { name: attribute(match[0], 'name'), rows, merges, cells };
  });
  return { sheets };
}

/**
 * An .xlsx file of `sheets` ({ name, rows, merges? }) with shared strings, as Excel writes them.
 * For fixtures: it writes values and merges, no styles.
 */
export function writeXlsx({ sheets }) {
  const strings = [];
  const stringIndex = new Map();
  const shared = (value) => {
    if (!stringIndex.has(value)) {
      stringIndex.set(value, strings.length);
      strings.push(value);
    }
    return stringIndex.get(value);
  };
  const sheetParts = sheets.map((sheet, index) => {
    const rows = sheet.rows
      .map((row, rowIndex) => {
        const cells = row
          .map((value, column) => {
            if (value === null || value === undefined || value === '') return '';
            const ref = `${columnLetters(column)}${rowIndex + 1}`;
            return typeof value === 'number'
              ? `<c r="${ref}"><v>${value}</v></c>`
              : `<c r="${ref}" t="s"><v>${shared(String(value))}</v></c>`;
          })
          .join('');
        return `<row r="${rowIndex + 1}">${cells}</row>`;
      })
      .join('');
    const merges = sheet.merges?.length
      ? `<mergeCells count="${sheet.merges.length}">${sheet.merges.map((ref) => `<mergeCell ref="${ref}"/>`).join('')}</mergeCells>`
      : '';
    return {
      name: `xl/worksheets/sheet${index + 1}.xml`,
      data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>${rows}</sheetData>${merges}</worksheet>`,
    };
  });
  const ns = 'http://schemas.openxmlformats.org';
  return writeZip([
    {
      name: '[Content_Types].xml',
      data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="${ns}/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>${sheets.map((_, index) => `<Override PartName="/xl/worksheets/sheet${index + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}<Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/></Types>`,
    },
    {
      name: '_rels/.rels',
      data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="${ns}/package/2006/relationships"><Relationship Id="rId1" Type="${ns}/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`,
    },
    {
      name: 'xl/workbook.xml',
      data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="${ns}/spreadsheetml/2006/main" xmlns:r="${ns}/officeDocument/2006/relationships"><sheets>${sheets.map((sheet, index) => `<sheet name="${encode(sheet.name)}" sheetId="${index + 1}" r:id="rId${index + 1}"/>`).join('')}</sheets></workbook>`,
    },
    {
      name: 'xl/_rels/workbook.xml.rels',
      data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="${ns}/package/2006/relationships">${sheets.map((_, index) => `<Relationship Id="rId${index + 1}" Type="${ns}/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${index + 1}.xml"/>`).join('')}<Relationship Id="rId${sheets.length + 1}" Type="${ns}/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/></Relationships>`,
    },
    ...sheetParts,
    {
      name: 'xl/sharedStrings.xml',
      data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><sst xmlns="${ns}/spreadsheetml/2006/main" count="${strings.length}" uniqueCount="${strings.length}">${strings.map((value) => `<si><t xml:space="preserve">${encode(value)}</t></si>`).join('')}</sst>`,
    },
  ]);
}

// ---------- docx ----------

/** The paragraphs of a .docx file's body, each with its paragraph style (or null) and its text. */
export function readDocx(buffer) {
  const xml = readZip(buffer).get('word/document.xml')?.toString('utf8');
  if (xml === undefined) throw new Error('not a .docx file (no word/document.xml)');
  const paragraphs = [...xml.matchAll(/<w:p\b[^>]*?(?:\/>|>([\s\S]*?)<\/w:p>)/gu)]
    .map((match) => {
      const inner = match[1] ?? '';
      const style = /<w:pStyle\b[^>]*>/u.exec(inner);
      return { style: style ? attribute(style[0], 'w:val') : null, text: textOf(inner, 'w:t') };
    })
    .filter((paragraph) => paragraph.text.trim() !== '');
  return { paragraphs };
}

/** A .docx file of `paragraphs` ({ style?, text }). For fixtures: text and paragraph styles only. */
export function writeDocx({ paragraphs }) {
  const ns = 'http://schemas.openxmlformats.org';
  const body = paragraphs
    .map(({ style, text }) => {
      const properties = style ? `<w:pPr><w:pStyle w:val="${encode(style)}"/></w:pPr>` : '';
      return `<w:p>${properties}<w:r><w:t xml:space="preserve">${encode(text)}</w:t></w:r></w:p>`;
    })
    .join('');
  return writeZip([
    {
      name: '[Content_Types].xml',
      data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="${ns}/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>`,
    },
    {
      name: '_rels/.rels',
      data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="${ns}/package/2006/relationships"><Relationship Id="rId1" Type="${ns}/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>`,
    },
    {
      name: 'word/document.xml',
      data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="${ns}/wordprocessingml/2006/main"><w:body>${body}</w:body></w:document>`,
    },
  ]);
}

// ---------- command line ----------

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const [kind, file, output] = process.argv.slice(2);
  if (kind === 'write' && file !== undefined && output !== undefined) {
    const spec = JSON.parse(readFileSync(file, 'utf8'));
    writeFileSync(output, output.endsWith('.docx') ? writeDocx(spec) : writeXlsx(spec));
    process.stdout.write(`${JSON.stringify({ wrote: output })}\n`);
  } else if ((kind === 'xlsx' || kind === 'docx') && file !== undefined) {
    try {
      refuseLargeFile(statSync(file).size);
      const buffer = readFileSync(file);
      const json = `${JSON.stringify(kind === 'xlsx' ? readXlsx(buffer) : readDocx(buffer), null, 2)}\n`;
      if (kind === 'docx' && output !== undefined) {
        mkdirSync(dirname(output), { recursive: true });
        writeFileSync(output, json);
        process.stdout.write(`${JSON.stringify({ written: output })}\n`);
      } else {
        process.stdout.write(json);
      }
    } catch (error) {
      if (!(error instanceof OoxmlRefusal)) throw error;
      process.stderr.write(`${JSON.stringify({ error: error.code, message: error.message })}\n`);
      process.exit(1);
    }
  } else {
    process.stderr.write(
      'usage: node ooxml.mjs xlsx <file> | docx <file> [out.json] | write <spec.json> <out.xlsx|out.docx>\n',
    );
    process.exit(2);
  }
}

#!/usr/bin/env node
/* global Buffer, process */ // The root ESLint config declares no environment globals.
// Read the text of a PDF with Node alone.
//
// It scans the file for `N G obj` bodies (so a damaged or missing cross-reference table does not
// matter), unpacks `/ObjStm` object streams, walks the page tree, and runs each page's content
// stream for the text operators, mapping character codes through `/ToUnicode` CMaps (what makes
// Japanese Identity-H fonts readable). It is the script the office-reader skill runs inside a
// run's sandbox, where Node is all there is.
//
//   node pdf.mjs <file>   → { pages: [{ number, text, unreadable? }] }
//
// A page with no text is `""` (an image-only scan: there is no OCR). `unreadable: true` marks a
// page that has text this script cannot decode (a filter other than Flate, or a composite font with
// no ToUnicode map). A password-protected file is refused, with no text, as `encrypted_pdf`. A file
// that is too big to read safely is refused as `file_too_large`, `too_many_objects`,
// `too_many_pages`, `page_tree_too_deep`, `stream_too_large` or `inflated_too_large` (see
// PDF_LIMITS).
import { readFileSync, statSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { constants, inflateSync } from 'node:zlib';

/** Why a file was refused; `code` is the name an agent reports. */
export class PdfRefusal extends Error {
  constructor(code, message) {
    super(message);
    this.name = 'PdfRefusal';
    this.code = code;
  }
}

/**
 * What one file may cost. A PDF comes from outside, and a few kilobytes of Flate can inflate to
 * gigabytes, so the file, the object and page counts, and what streams inflate to are all capped.
 */
export const PDF_LIMITS = Object.freeze({
  fileBytes: 50 * 1024 * 1024,
  objects: 100_000,
  pages: 2_000,
  pageTreeDepth: 64,
  streamBytes: 64 * 1024 * 1024,
  inflatedBytes: 256 * 1024 * 1024,
});

/** A feature this reader does not implement; the page that needs it is reported unreadable. */
class Unsupported extends Error {}

// ---------- objects ----------

const SPACE = /[\0\t\n\f\r ]/u;

function skipSpace(s, start) {
  let i = start;
  while (i < s.length) {
    if (SPACE.test(s[i] ?? '')) i += 1;
    else if (s[i] === '%') while (i < s.length && s[i] !== '\n' && s[i] !== '\r') i += 1;
    else break;
  }
  return i;
}

const ESCAPES = { n: '\n', r: '\r', t: '\t', b: '\b', f: '\f' };

function literalString(s, start) {
  let depth = 0;
  let out = '';
  let i = start;
  for (; i < s.length; i += 1) {
    const c = s[i] ?? '';
    if (c === '\\') {
      i += 1;
      const next = s[i] ?? '';
      const octal = /^[0-7]{1,3}/u.exec(s.slice(i, i + 3));
      if (octal) {
        out += String.fromCharCode(parseInt(octal[0], 8) & 0xff);
        i += octal[0].length - 1;
      } else if (next === '\r') {
        if (s[i + 1] === '\n') i += 1;
      } else if (next !== '\n') out += ESCAPES[next] ?? next;
    } else if (c === '(') {
      depth += 1;
      if (depth > 1) out += c;
    } else if (c === ')') {
      depth -= 1;
      if (depth === 0) return [{ string: out }, i + 1];
      out += c;
    } else out += c;
  }
  throw new Error('unterminated string');
}

function hexString(s, start) {
  const end = s.indexOf('>', start);
  if (end < 0) throw new Error('unterminated hex string');
  let hex = s.slice(start + 1, end).replace(/\s/gu, '');
  if (hex.length % 2 === 1) hex += '0';
  return [{ string: Buffer.from(hex, 'hex').toString('latin1') }, end + 1];
}

const NUMBER = /[+-]?(?:\d+\.?\d*|\.\d+)/uy;
const REFERENCE = /\s+(\d+)\s+R(?![\w])/uy;
const KEYWORD = /[^\s()<>[\]{}/%]+/uy;

/**
 * One PDF object starting at `start`: a number, `/Name` (kept with its slash), `{ string }`,
 * `{ ref }`, an array, a dictionary (no prototype) or a boolean or null.
 */
function parseValue(s, start) {
  const i = skipSpace(s, start);
  const c = s[i] ?? '';
  if (c === '<' && s[i + 1] === '<') {
    const dict = Object.create(null);
    let at = skipSpace(s, i + 2);
    while (!(s[at] === '>' && s[at + 1] === '>')) {
      if (s[at] !== '/') throw new Error('dictionary key is not a name');
      const [key, afterKey] = parseValue(s, at);
      const [value, afterValue] = parseValue(s, afterKey);
      dict[key.slice(1)] = value;
      at = skipSpace(s, afterValue);
    }
    return [dict, at + 2];
  }
  if (c === '[') {
    const items = [];
    let at = skipSpace(s, i + 1);
    while (s[at] !== ']') {
      const [item, after] = parseValue(s, at);
      items.push(item);
      at = skipSpace(s, after);
    }
    return [items, at + 1];
  }
  if (c === '(') return literalString(s, i);
  if (c === '<') return hexString(s, i);
  if (c === '/') {
    KEYWORD.lastIndex = i + 1;
    const name = KEYWORD.exec(s)?.[0] ?? '';
    const decoded = name.replace(/#([0-9a-f]{2})/giu, (_, hex) =>
      String.fromCharCode(parseInt(hex, 16)),
    );
    return [`/${decoded}`, i + 1 + name.length];
  }
  NUMBER.lastIndex = i;
  const number = NUMBER.exec(s);
  if (number) {
    const after = i + number[0].length;
    if (/^\d+$/u.test(number[0])) {
      REFERENCE.lastIndex = after;
      const ref = REFERENCE.exec(s);
      // `12 0 R` is a reference only when a generation number and R follow the object number.
      if (ref) return [{ ref: Number(number[0]) }, after + ref[0].length];
    }
    return [Number(number[0]), after];
  }
  KEYWORD.lastIndex = i;
  const word = KEYWORD.exec(s)?.[0];
  if (word === 'true') return [true, i + 4];
  if (word === 'false') return [false, i + 5];
  if (word === 'null') return [null, i + 4];
  throw new Error(`unexpected ${JSON.stringify(word ?? c)}`);
}

const isDict = (value) =>
  typeof value === 'object' &&
  value !== null &&
  !Array.isArray(value) &&
  !('ref' in value) &&
  !('string' in value);

class Document {
  constructor(buffer, limits) {
    this.limits = limits;
    this.objects = new Map();
    this.inflated = 0;
    const s = buffer.toString('latin1');
    const objectHeader = /(\d+)\s+(\d+)\s+obj\b/gu;
    for (let match = objectHeader.exec(s); match; match = objectHeader.exec(s)) {
      let value;
      let at;
      try {
        [value, at] = parseValue(s, objectHeader.lastIndex);
      } catch {
        continue;
      }
      const object = { value, stream: null };
      at = skipSpace(s, at);
      if (isDict(value) && s.startsWith('stream', at)) {
        let begin = at + 6;
        if (s[begin] === '\r') begin += 1;
        if (s[begin] === '\n') begin += 1;
        const end = s.indexOf('endstream', begin);
        if (end >= 0) {
          object.stream = buffer.subarray(begin, end);
          objectHeader.lastIndex = end;
        }
      }
      this.add(Number(match[1]), object);
    }
    this.refuseEncrypted(s);
    this.unpackObjectStreams();
  }

  add(number, object) {
    this.objects.set(number, object);
    if (this.objects.size > PDF_LIMITS.objects)
      throw new PdfRefusal(
        'too_many_objects',
        `the PDF holds more than ${PDF_LIMITS.objects} objects; it is not read`,
      );
  }

  // The `/Encrypt` entry sits in a classic trailer or, with cross-reference streams, in the dictionary
  // of the `/XRef` stream. It is checked before any stream is read.
  refuseEncrypted(s) {
    const dictionaries = [...this.objects.values()]
      .map((object) => object.value)
      .filter((value) => isDict(value) && value.Type === '/XRef');
    for (const trailer of s.matchAll(/trailer\s*/gu)) {
      try {
        dictionaries.push(parseValue(s, trailer.index + trailer[0].length)[0]);
      } catch {
        // A trailer this reader cannot parse is not evidence of encryption.
      }
    }
    if (dictionaries.some((dict) => isDict(dict) && (dict.Encrypt ?? null) !== null))
      throw new PdfRefusal('encrypted_pdf', 'the PDF is password-protected; it cannot be read');
  }

  unpackObjectStreams() {
    for (const object of [...this.objects.values()]) {
      if (!isDict(object.value) || object.value.Type !== '/ObjStm' || object.stream === null)
        continue;
      try {
        const text = this.streamData(object).toString('latin1');
        const first = Number(this.deref(object.value.First));
        const header = text.slice(0, first).trim().split(/\s+/u).map(Number);
        const count = Math.min(Number(this.deref(object.value.N)), header.length / 2);
        for (let index = 0; index < count; index += 1) {
          const number = header[index * 2];
          const offset = header[index * 2 + 1];
          if (number === undefined || offset === undefined || this.objects.has(number)) continue;
          this.add(number, { value: parseValue(text, first + offset)[0], stream: null });
        }
      } catch (error) {
        if (error instanceof PdfRefusal) throw error;
        // An object stream that cannot be opened leaves its objects missing; the pages that
        // needed them come out unreadable.
      }
    }
  }

  deref(value) {
    let current = value;
    for (let hops = 0; hops < 32 && current && typeof current === 'object' && 'ref' in current;) {
      current = this.objects.get(current.ref)?.value;
      hops += 1;
    }
    return current;
  }

  /** The object a value refers to, with its raw stream, or null. */
  objectOf(value) {
    return value && typeof value === 'object' && 'ref' in value
      ? (this.objects.get(value.ref) ?? null)
      : null;
  }

  inflate(data) {
    const limit = Math.max(
      1,
      Math.min(this.limits.streamBytes, this.limits.inflatedBytes - this.inflated),
    );
    let out;
    try {
      out = inflateSync(data, { finishFlush: constants.Z_SYNC_FLUSH, maxOutputLength: limit });
    } catch (error) {
      if (error?.code !== 'ERR_BUFFER_TOO_LARGE') throw error;
      throw limit < this.limits.streamBytes
        ? new PdfRefusal(
            'inflated_too_large',
            `the streams inflate to more than ${this.limits.inflatedBytes} bytes in all`,
          )
        : new PdfRefusal(
            'stream_too_large',
            `a stream inflates to more than ${this.limits.streamBytes} bytes`,
          );
    }
    this.inflated += out.length;
    return out;
  }

  streamData(object) {
    const filter = this.deref(object.value.Filter);
    const filters = Array.isArray(filter) ? filter.map((f) => this.deref(f)) : [filter];
    let data = object.stream;
    for (const name of filters) {
      if (name === undefined || name === null) continue;
      if (name !== '/FlateDecode' && name !== '/Fl') throw new Unsupported(`filter ${name}`);
      data = this.inflate(data);
    }
    const parameters = this.deref(object.value.DecodeParms);
    if (isDict(parameters) && Number(this.deref(parameters.Predictor) ?? 1) > 1)
      throw new Unsupported('predictor');
    return data;
  }

  pages() {
    const catalog = [...this.objects.values()].find(
      (object) => isDict(object.value) && object.value.Type === '/Catalog',
    );
    const found = [];
    const seen = new Set();
    const walk = (node, inherited, depth) => {
      const dict = this.deref(node);
      if (!isDict(dict) || seen.has(dict)) return;
      if (depth > PDF_LIMITS.pageTreeDepth)
        throw new PdfRefusal(
          'page_tree_too_deep',
          `the PDF page tree is nested more than ${PDF_LIMITS.pageTreeDepth} levels; it is not read`,
        );
      seen.add(dict);
      const resources = dict.Resources ?? inherited;
      const kids = this.deref(dict.Kids);
      if (Array.isArray(kids)) for (const kid of kids) walk(kid, resources, depth + 1);
      else {
        if (found.length >= PDF_LIMITS.pages)
          throw new PdfRefusal(
            'too_many_pages',
            `the PDF has more than ${PDF_LIMITS.pages} pages; it is not read`,
          );
        found.push({ dict, resources });
      }
    };
    if (catalog) walk(catalog.value.Pages, undefined, 0);
    else
      for (const object of this.objects.values())
        if (isDict(object.value) && object.value.Type === '/Page') {
          if (found.length >= PDF_LIMITS.pages)
            throw new PdfRefusal(
              'too_many_pages',
              `the PDF has more than ${PDF_LIMITS.pages} pages; it is not read`,
            );
          found.push({ dict: object.value, resources: object.value.Resources });
        }
    return found;
  }
}

// ---------- fonts ----------

const utf16 = (hex) =>
  hex.length <= 2
    ? String.fromCharCode(parseInt(hex, 16))
    : (hex.match(/.{1,4}/gu) ?? []).map((unit) => String.fromCharCode(parseInt(unit, 16))).join('');

const HEX = '[0-9A-Fa-f]';

/** The code → text map of a ToUnicode CMap, and the byte width of its codes (0 if not stated). */
function parseCMap(text) {
  const map = new Map();
  const space = new RegExp(`begincodespacerange\\s*<(${HEX}+)>`, 'u').exec(text);
  const width = space ? (space[1] ?? '').length / 2 : 0;
  for (const block of text.matchAll(/beginbfchar([\s\S]*?)endbfchar/gu))
    for (const pair of (block[1] ?? '').matchAll(new RegExp(`<(${HEX}+)>\\s*<(${HEX}*)>`, 'gu')))
      map.set(parseInt(pair[1] ?? '', 16), utf16(pair[2] ?? ''));
  const range = new RegExp(`<(${HEX}+)>\\s*<(${HEX}+)>\\s*(<${HEX}*>|\\[[^\\]]*\\])`, 'gu');
  for (const block of text.matchAll(/beginbfrange([\s\S]*?)endbfrange/gu)) {
    for (const entry of (block[1] ?? '').matchAll(range)) {
      const low = parseInt(entry[1] ?? '', 16);
      const high = Math.min(parseInt(entry[2] ?? '', 16), low + 0xffff);
      const target = entry[3] ?? '';
      const list = target.startsWith('[')
        ? [...target.matchAll(new RegExp(`<(${HEX}*)>`, 'gu'))].map((one) => utf16(one[1] ?? ''))
        : null;
      const base = list ? '' : utf16(target.slice(1, -1));
      for (let code = low; code <= high; code += 1) {
        const text16 = list
          ? (list[code - low] ?? '')
          : base.slice(0, -1) + String.fromCharCode(base.charCodeAt(base.length - 1) + code - low);
        map.set(code, text16);
      }
    }
  }
  return { map, width };
}

// ---------- text ----------

function pageContent(document, page) {
  const contents = document.deref(page.dict.Contents);
  const parts = Array.isArray(contents) ? contents : [page.dict.Contents];
  return parts
    .map((part) => document.objectOf(part))
    .filter((object) => object !== null && object.stream !== null)
    .map((object) => document.streamData(object).toString('latin1'))
    .join('\n');
}

class TextReader {
  constructor(document) {
    this.document = document;
    this.fonts = new Map();
    this.parts = [];
    this.unreadable = false;
  }

  font(resources, name) {
    const { document } = this;
    const fonts = document.deref(document.deref(resources)?.Font);
    const reference = isDict(fonts) ? fonts[name.slice(1)] : undefined;
    const dict = document.deref(reference);
    if (!isDict(dict)) return null;
    let font = this.fonts.get(dict);
    if (font === undefined) {
      const composite = document.deref(dict.Subtype) === '/Type0';
      const toUnicode = document.objectOf(dict.ToUnicode);
      let cmap = null;
      if (toUnicode?.stream) {
        try {
          cmap = parseCMap(document.streamData(toUnicode).toString('latin1'));
        } catch (error) {
          if (error instanceof PdfRefusal) throw error;
          cmap = null;
        }
      }
      font = { composite, cmap };
      this.fonts.set(dict, font);
    }
    return font;
  }

  show(font, string) {
    if (font?.cmap) {
      const width = font.cmap.width || (font.composite ? 2 : 1);
      for (let at = 0; at < string.length; at += width) {
        let code = 0;
        for (let byte = 0; byte < width; byte += 1)
          code = code * 256 + (string.charCodeAt(at + byte) || 0);
        this.parts.push(font.cmap.map.get(code) ?? '');
      }
    } else if (font?.composite) {
      this.unreadable = true;
    } else this.parts.push(string);
  }

  run(content, resources, depth) {
    let font = null;
    let operands = [];
    let lastTm = null;
    let at = 0;
    while (true) {
      at = skipSpace(content, at);
      if (at >= content.length) break;
      if (/[-+.\d/(<[]/u.test(content[at] ?? '')) {
        const [value, next] = parseValue(content, at);
        operands.push(value);
        at = next;
        continue;
      }
      KEYWORD.lastIndex = at;
      const operator = KEYWORD.exec(content)?.[0];
      if (operator === undefined) {
        at += 1;
        continue;
      }
      at += operator.length;
      const [first, second, , , tmX, tmY] = operands;
      switch (operator) {
        case 'BT':
          this.parts.push('\n');
          lastTm = null;
          break;
        case 'Tf':
          font = typeof first === 'string' ? this.font(resources, first) : null;
          break;
        case 'Tj':
          if (first?.string !== undefined) this.show(font, first.string);
          break;
        case 'TJ':
          for (const item of Array.isArray(first) ? first : []) {
            if (item?.string !== undefined) this.show(font, item.string);
            else if (typeof item === 'number' && item < -200) this.parts.push(' ');
          }
          break;
        case "'":
        case '"': {
          this.parts.push('\n');
          const shown = operator === '"' ? operands[2] : first;
          if (shown?.string !== undefined) this.show(font, shown.string);
          break;
        }
        case 'Td':
        case 'TD':
          if (Number(second) !== 0) this.parts.push('\n');
          else if (Number(first) !== 0) this.parts.push(' ');
          break;
        case 'T*':
          this.parts.push('\n');
          break;
        case 'Tm':
          if (lastTm !== null)
            this.parts.push(tmY === lastTm.y ? (tmX === lastTm.x ? '' : ' ') : '\n');
          lastTm = { x: tmX, y: tmY };
          break;
        case 'Do':
          if (typeof first === 'string' && depth < 8) this.form(resources, first, depth);
          break;
        case 'BI': {
          const end = content.slice(at).search(/\sEI(?=\s|$)/u);
          at = end < 0 ? content.length : at + end + 3;
          break;
        }
        default:
          break;
      }
      operands = [];
    }
  }

  form(resources, name, depth) {
    const { document } = this;
    const xobjects = document.deref(document.deref(resources)?.XObject);
    const object = isDict(xobjects) ? document.objectOf(xobjects[name.slice(1)]) : null;
    if (
      !object?.stream ||
      !isDict(object.value) ||
      document.deref(object.value.Subtype) !== '/Form'
    )
      return;
    this.run(
      document.streamData(object).toString('latin1'),
      object.value.Resources ?? resources,
      depth + 1,
    );
  }
}

function tidy(text) {
  return text
    .split('\n')
    .map((line) => line.replace(/\s+/gu, ' ').trim())
    .filter((line) => line !== '')
    .join('\n');
}

function refuseLargeFile(size) {
  if (size > PDF_LIMITS.fileBytes)
    throw new PdfRefusal(
      'file_too_large',
      `the file is ${size} bytes; at most ${PDF_LIMITS.fileBytes} are read`,
    );
}

/**
 * The text of every page of a PDF, in page order.
 *
 * @param {Buffer} buffer
 * @param {{ streamBytes: number, inflatedBytes: number }} [limits] the inflate caps; tests pass small ones
 * @returns {{ pages: { number: number, text: string, unreadable?: true }[] }}
 * @throws {PdfRefusal} `not_a_pdf`, `encrypted_pdf`, `corrupt_pdf`, or a size limit: `file_too_large`,
 *   `too_many_objects`, `too_many_pages`, `page_tree_too_deep`, `stream_too_large` or
 *   `inflated_too_large`.
 */
export function readPdf(buffer, limits = PDF_LIMITS) {
  refuseLargeFile(buffer.length);
  if (!buffer.subarray(0, 1024).toString('latin1').includes('%PDF-'))
    throw new PdfRefusal('not_a_pdf', 'the file does not start with %PDF-');
  let document;
  try {
    document = new Document(buffer, limits);
  } catch (error) {
    if (error instanceof PdfRefusal) throw error;
    throw new PdfRefusal('corrupt_pdf', 'the PDF structure could not be read');
  }
  const found = document.pages();
  if (found.length === 0) throw new PdfRefusal('corrupt_pdf', 'the PDF has no readable page tree');
  const pages = found.map((page, index) => {
    const reader = new TextReader(document);
    try {
      reader.run(pageContent(document, page), page.resources, 0);
    } catch (error) {
      if (error instanceof PdfRefusal) throw error;
      reader.unreadable = true;
    }
    const text = tidy(reader.parts.join(''));
    return { number: index + 1, text, ...(reader.unreadable ? { unreadable: true } : {}) };
  });
  return { pages };
}

// ---------- command line ----------

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const file = process.argv[2];
  if (file === undefined || process.argv.length !== 3) {
    process.stderr.write('usage: node pdf.mjs <file>\n');
    process.exit(2);
  }
  try {
    refuseLargeFile(statSync(file).size);
    process.stdout.write(`${JSON.stringify(readPdf(readFileSync(file)), null, 2)}\n`);
  } catch (error) {
    if (!(error instanceof PdfRefusal)) throw error;
    process.stderr.write(`${JSON.stringify({ error: error.code, message: error.message })}\n`);
    process.exit(1);
  }
}
